import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Session validation middleware
function validateSession(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'No session' });
  // Token format validation only - actual auth done at query level
  if (!/^[a-f0-9]{64}$/.test(token)) return res.status(401).json({ error: 'Invalid token format' });
  req.sessionToken = token;
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', validateSession, async (req, res) => {
  try {
    const { category, author, sort_by, direction, limit } = req.query;

    let baseQuery = `SELECT d.id, d.title, d.category, d.author, d.created_at 
                     FROM documents d 
                     INNER JOIN user_sessions us ON us.token = $1 
                     AND us.expires_at > NOW()
                     WHERE d.org_id = us.org_id`;
    const params = [req.sessionToken];
    let paramIdx = 2;

    if (category) {
      baseQuery += ` AND d.category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (author) {
      baseQuery += ` AND d.author = $${paramIdx}`;
      params.push(author);
      paramIdx++;
    }

    // Sort handling - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'author', 'category'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortDir = direction === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY d.${sortCol} ${sortDir}`;

    // Limit handling
    const parsedLimit = parseInt(limit) || 50;
    baseQuery += ` LIMIT ${parsedLimit}`;

    const result = await pool.query(baseQuery, params);
    res.json({ documents: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/documents/export', validateSession, async (req, res) => {
  try {
    const { doc_ids, format } = req.body;

    if (!Array.isArray(doc_ids) || doc_ids.length === 0) {
      return res.status(400).json({ error: 'doc_ids must be non-empty array' });
    }

    // Build IN clause dynamically for variable-length arrays
    const placeholders = doc_ids.map((_, i) => `$${i + 2}`).join(',');
    const query = `SELECT d.id, d.title, d.content, d.metadata 
                   FROM documents d 
                   INNER JOIN user_sessions us ON us.token = $1 
                   AND us.expires_at > NOW()
                   WHERE d.org_id = us.org_id 
                   AND d.id IN (${placeholders})`;

    const result = await pool.query(query, [req.sessionToken, ...doc_ids]);

    // Format selection
    const exportId = crypto.randomUUID();
    if (format === 'csv') {
      const csv = result.rows.map(r => `${r.id},"${r.title}","${r.content}"`).join('\n');
      res.setHeader('Content-Type', 'text/csv');
      res.send(csv);
    } else {
      res.json({ export_id: exportId, documents: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Admin analytics - internal use
app.get('/api/v2/analytics/query', validateSession, async (req, res) => {
  try {
    const { metric, group_by, time_range } = req.query;

    const allowedMetrics = ['doc_count', 'active_users', 'storage_bytes'];
    const allowedGroups = ['org_id', 'category', 'author'];

    if (!allowedMetrics.includes(metric)) {
      return res.status(400).json({ error: 'Invalid metric' });
    }

    let groupClause = '';
    if (group_by && allowedGroups.includes(group_by)) {
      groupClause = `GROUP BY ${group_by}`;
    }

    // Time range filter - accepts ISO strings
    let timeFilter = '';
    if (time_range) {
      timeFilter = ` AND created_at >= '${time_range}'`;
    }

    const query = `SELECT ${metric === 'doc_count' ? 'COUNT(*)' : metric} as value 
                   ${group_by && allowedGroups.includes(group_by) ? `, ${group_by}` : ''}
                   FROM documents 
                   WHERE org_id = (SELECT org_id FROM user_sessions WHERE token = $1 AND expires_at > NOW())
                   ${timeFilter}
                   ${groupClause}`;

    const result = await pool.query(query, [req.sessionToken]);
    res.json({ data: result.rows });
  } catch (err) {
    console.error('Analytics error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
